package Activitats;

public class Act10 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int myLuckyNumber = 13;
		//myLuckyNumber es 13;
		System.out.println(myLuckyNumber + 1);
		//Mostra 14 perquè 13 + 1 = 14;
		System.out.println(myLuckyNumber);
		//Mostra 13 perquè la variable no ha canviat;
		myLuckyNumber = 5 + 2;
		//Assignem un nou valor a la variable;
		System.out.println(myLuckyNumber);
		//Mostra 7;
	}

}
